urllib3.util.ssl_.is_ipaddress:
def is_ipaddress(hostname: str | bytes) -> bool:
    """Detects whether the hostname given is an IPv4 or IPv6 address.
    Also detects IPv6 addresses with Zone IDs.

    :param str hostname: Hostname to examine.
    :return: True if the hostname is an IP address, False otherwise.
    """
    if isinstance(hostname, bytes):
        hostname = hostname.decode('ascii')
    return bool((_IPV4_RE.match(hostname) or _BRACELESS_IPV6_ADDRZ_RE.match(hostname)))

urllib3.util.ssl_._is_key_file_encrypted:
def _is_key_file_encrypted(key_file: str) -> bool:
    """Detects if a key file is encrypted or not."""
    with open(key_file) as f:
        for line in f:
            if 'ENCRYPTED' in line:
                return True
    return False

urllib3.connection._ssl_wrap_socket_and_:
def _ssl_wrap_socket_and_match_hostname(sock: socket.socket, *, cert_reqs: None | str | int, ssl_version: None | str | int, ssl_minimum_version: int | None, ssl_maximum_version: int | None, cert_file: str | None, key_file: str | None, key_password: str | None, ca_certs: str | None, ca_cert_dir: str | None, ca_cert_data: None | str | bytes, assert_hostname: None | str | typing.Literal[False], assert_fingerprint: str | None, server_hostname: str | None, ssl_context: ssl.SSLContext | None, tls_in_tls: bool = False) -> _WrappedAndVerifiedSocket:
    """Logic for constructing an SSLContext from all TLS parameters, passing
    that down into ssl_wrap_socket, and then doing certificate verification
    either via hostname or fingerprint. This function exists to guarantee
    that both proxies and targets have the same behavior when connecting via TLS.
    """
    default_ssl_context = False
    if ssl_context is None:
        default_ssl_context = True
        context = create_urllib3_context(ssl_version=resolve_ssl_version(ssl_version), ssl_minimum_version=ssl_minimum_version, ssl_maximum_version=ssl_maximum_version, cert_reqs=resolve_cert_reqs(cert_reqs))
    else:
        context = ssl_context
    context.verify_mode = resolve_cert_reqs(cert_reqs)
    if (assert_fingerprint or assert_hostname or assert_hostname is False or ssl_.IS_PYOPENSSL or not ssl_.HAS_NEVER_CHECK_COMMON_NAME):
        context.check_hostname = False
    if (not ca_certs and not ca_cert_dir and not ca_cert_data and default_ssl_context and hasattr(context, 'load_default_certs')):
        context.load_default_certs()
    if server_hostname is not None:
        normalized = server_hostname.strip('[]')
        if '%' in normalized:
            normalized = normalized[:normalized.rfind('%')]
        if is_ipaddress(normalized):
            server_hostname = normalized
    ssl_sock = ssl_wrap_socket(sock=sock, keyfile=key_file, certfile=cert_file, key_password=key_password, ca_certs=ca_certs, ca_cert_dir=ca_cert_dir, ca_cert_data=ca_cert_data, server_hostname=server_hostname, ssl_context=context, tls_in_tls=tls_in_tls)
    try:
        if assert_fingerprint:
            _assert_fingerprint(ssl_sock.getpeercert(binary_form=True), assert_fingerprint)
        elif (context.verify_mode != ssl.CERT_NONE and not context.check_hostname and assert_hostname is not False):
            cert: _TYPE_PEER_CERT_RET_DICT = ssl_sock.getpeercert()
            if default_ssl_context:
                hostname_checks_common_name = False
            else:
                hostname_checks_common_name = (getattr(context, 'hostname_checks_common_name', False) or False)
            _match_hostname(cert, (assert_hostname or server_hostname), hostname_checks_common_name)
        return _WrappedAndVerifiedSocket(socket=ssl_sock, is_verified=(context.verify_mode == ssl.CERT_REQUIRED or bool(assert_fingerprint)))
    except BaseException:
        ssl_sock.close()
        raise

urllib3.util.ssl_._ssl_wrap_socket_impl:
def _ssl_wrap_socket_impl(sock: socket.socket, ssl_context: ssl.SSLContext, tls_in_tls: bool, server_hostname: str | None = None) -> ssl.SSLSocket | SSLTransportType:
    if tls_in_tls:
        if not SSLTransport:
            raise ProxySchemeUnsupported("TLS in TLS requires support for the 'ssl' module")
        SSLTransport._validate_ssl_context_for_tls_in_tls(ssl_context)
        return SSLTransport(sock, ssl_context, server_hostname)
    return ssl_context.wrap_socket(sock, server_hostname=server_hostname)

urllib3.util.ssl_.resolve_ssl_version:
def resolve_ssl_version(candidate: None | int | str) -> int:
    """
    like resolve_cert_reqs
    """
    if candidate is None:
        return PROTOCOL_TLS
    if isinstance(candidate, str):
        res = getattr(ssl, candidate, None)
        if res is None:
            res = getattr(ssl, 'PROTOCOL_' + candidate)
        return typing.cast(int, res)
    return candidate

urllib3.connection._match_hostname:
def _match_hostname(cert: _TYPE_PEER_CERT_RET_DICT | None, asserted_hostname: str, hostname_checks_common_name: bool = False) -> None:
    stripped_hostname = asserted_hostname.strip('[]')
    if is_ipaddress(stripped_hostname):
        asserted_hostname = stripped_hostname
    try:
        match_hostname(cert, asserted_hostname, hostname_checks_common_name)
    except CertificateError as e:
        log.warning('Certificate did not match expected hostname: %s. Certificate: %s', asserted_hostname, cert)
        e._peer_cert = cert
        raise

idna.core.check_nfc:
def check_nfc(label: str) -> None:
    """Require that a label is in Unicode Normalization Form C.

    :param label: The label to check.
    :raises IDNAError: If ``label`` differs from its NFC normalisation.
    """
    if len(label) > _max_input_length:
        raise IDNAError('Label too long')
    if unicodedata.normalize('NFC', label) != label:
        raise IDNAError('Label must be in Normalization Form C')

idna.core._joining_type:
def _joining_type(cp: int) -> Optional[str]:
    for (jt, ranges) in idnadata.joining_types.items():
        if intranges_contain(cp, ranges):
            return jt
    return None
